def de_bruijn(k, n):
    """
    De Bruijn sequence for alphabet k and subsequences of length n.
    """
    alphabet = list(range(k))
    a = [0] * (k * n + 1)
    sequence = []

    def generate(t, p):
        if t > n:
            if n % p == 0:
                for i in range(1, p + 1):
                    sequence.append(a[i])
        else:
            a[t] = a[t - p]
            generate(t + 1, p)
            for j in range(a[t - p] + 1, k):
                a[t] = j
                generate(t + 1, t)

    generate(1, 1)
    return sequence

seq = de_bruijn(3, 6)
