# Verify the sequence
def verify_de_bruijn(seq, k, n):
    if len(seq) != k**n:
        return False
    seen = set()
    for i in range(len(seq)):
        sub = tuple(seq[(i + j) % len(seq)] for j in range(n))
        if sub in seen:
            return False
        seen.add(sub)
    return len(seen) == k**n

print(verify_de_bruijn(seq, 3, 6))
